// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

/** A waiting committer may run the applier's next unit itself while the loop thread has nothing in hand. */
class ThreadApplierSchedulerTest {

	private ThreadApplierScheduler scheduler;

	@AfterEach
	void tearDown() {
		if (scheduler != null) {
			scheduler.shutdown();
		}
	}

	@Test
	void helpOnceRunsTheBodyOnTheCallingThreadWhileTheLoopIsIdle() throws Exception {
		scheduler = new ThreadApplierScheduler("test-applier");
		AtomicReference<Thread> runner = new AtomicReference<>();
		AtomicBoolean work = new AtomicBoolean();
		scheduler.start(() -> {
			if (work.compareAndSet(true, false)) {
				runner.set(Thread.currentThread());
				return true;
			}
			return false;
		});
		assertThat(ApplierStepping.awaitCondition(() -> !scheduler.loopThreadIsRunningForTest(), 5,
				TimeUnit.SECONDS)).as("the loop parks when it finds no work").isTrue();

		work.set(true);
		assertThat(scheduler.helpOnce()).as("the unit ran").isTrue();
		assertThat(runner.get()).isSameAs(Thread.currentThread());
		assertThat(scheduler.helpOnce()).as("nothing left to run").isFalse();
	}

	@Test
	void helpOnceDeclinesWhileTheLoopRunsAUnitAndWhilePaused() throws Exception {
		scheduler = new ThreadApplierScheduler("test-applier");
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicInteger units = new AtomicInteger();
		AtomicBoolean first = new AtomicBoolean(true);
		scheduler.start(() -> {
			if (first.compareAndSet(true, false)) {
				entered.countDown();
				try {
					release.await(10, TimeUnit.SECONDS);
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
				}
				units.incrementAndGet();
				return true;
			}
			return false;
		});
		assertThat(entered.await(10, TimeUnit.SECONDS)).isTrue();
		// the loop holds the unit: a helper neither runs concurrently nor waits for it
		assertThat(scheduler.helpOnce()).isFalse();
		release.countDown();
		assertThat(ApplierStepping.awaitCondition(() -> units.get() == 1, 5, TimeUnit.SECONDS)).isTrue();

		scheduler.pause();
		// a paused applier is a test condition; helpers must not run units behind the pausing test's back
		assertThat(scheduler.helpOnce()).isFalse();
		scheduler.resume();
	}
}
